@property
def _combined(self) -> IntervalSide:
    import numpy as np

    left = self.left._values.reshape(-1, 1)  # type: ignore[union-attr]
    right = self.right._values.reshape(-1, 1)  # type: ignore[union-attr]

    if needs_i8_conversion(left.dtype):
        # Combining left and right using np.concatenate and handling complex128
        comb = np.concatenate([left, right], axis=1)
        # View as complex128 for performance, if possible
        if comb.dtype.kind in ['i', 'u', 'f']:  # check if the dtype is integer, unsigned integer or float
            comb = comb.view('complex128')[:, 0]
        else:
            comb = comb.astype('complex128')[:, 0]
    else:
        # Construct complex numbers directly
        comb = (np.array(left.ravel(), dtype="complex128")) + (
            1j * np.array(right.ravel(), dtype="complex128")
        )

    return comb
